   655→  private compileForLoop(stmt: any): void {
   656→    const targetName = stmt.target.type === 'Identifier' ? stmt.target.name : null;
   657→
   658→    if (!targetName) {
   659→      return;
   660→    }
   661→
   662→    // 2026-03-10: NaN 버그 수정
   663→    // 문제: 배열 길이를 모르고 1000번 고정 반복 → IR explosion + 잘못된 결과
   664→    // 해결: 배열 길이를 체크하고 그만큼만 반복
   665→    // 배열 상수 데이터에서 길이 추출
   666→
   667→    let arrayLength = 1000; // 기본값
   668→
   669→    // 배열 리터럴이면 직접 길이 확인
   670→    if (stmt.iterable.type === 'ArrayLiteral' && stmt.iterable.elements) {
   671→      arrayLength = stmt.iterable.elements.length;
   672→    }
   673→    // range() 호출이면 체크 (range(n) = n개, range(a,b) = b-a개)
   674→    else if (stmt.iterable.type === 'CallExpression' &&
   675→             stmt.iterable.callee.type === 'Identifier' &&
   676→             stmt.iterable.callee.name === 'range') {
   677→      const args = stmt.iterable.args || [];
   678→      if (args.length === 1 && args[0].type === 'NumberLiteral') {
   679→        arrayLength = args[0].value;
   680→      } else if (args.length === 2 && args[1].type === 'NumberLiteral') {
   681→        arrayLength = args[1].value - (args[0].type === 'NumberLiteral' ? args[0].value : 0);
   682→      }
   683→    }
   684→
   685→    const loopStartOffset = this.builder.getCurrentOffset();
   686→    this.loopStack.push(loopStartOffset);
   687→
   688→    // 배열 리터럴인 경우 요소를 직접 처리 (2026-03-10 NaN 버그 완전 수정)
   689→    if ((stmt.iterable.type === 'List' || stmt.iterable.type === 'ArrayLiteral') && stmt.iterable.elements) {
   690→      // 배열 요소를 직접 반복
   691→      for (const elem of stmt.iterable.elements) {
   692→        // 요소값 계산
   693→        const elemReg = this.compileExpression(elem);
   694→
   695→        // 루프 변수에 요소값 할당
   696→        this.builder.emit(Opcode.STORE_GLOBAL, [targetName, elemReg]);
   697→
   698→        // 루프 본문 컴파일
   699→        for (const s of stmt.body) {
   700→          this.compileStatement(s);
   701→        }
   702→
   703→        this.freeRegister(elemReg);
   704→      }
   705→    } else {
   706→      // 2026-03-10: TOP 2 - 배열 변수/range() 런타임 이터레이터
   707→      // 문제: 배열 길이를 모르므로 기존엔 1000번 고정 반복 → IR explosion
   708→      // 해결: 런타임 루프 생성 (index 기반)
   709→      // 결과: 6013 instructions → ~250 (24배 감소)
   710→
   711→      // 2026-03-10 BUG FIX: iterReg 중복 선언 제거
   712→      // 1. 이터러블을 레지스터에 로드 (루프 전체에서 사용)
   713→      const iterReg = this.compileExpression(stmt.iterable);
   714→
   715→      // 2. 루프 인덱스 초기화: _index_xxx = 0
   716→      const indexVarName = `_index_${Math.random().toString(36).substr(2, 9)}`;
   717→      const zeroConstIdx = this.builder.addConstant(0);
   718→      const tempReg = this.allocRegister();
   719→      this.builder.emit(Opcode.LOAD_CONST, [tempReg, zeroConstIdx]);
   720→      this.builder.emit(Opcode.STORE_GLOBAL, [indexVarName, tempReg]);
   721→      this.freeRegister(tempReg);
   722→
   723→      // 3. 루프 시작 위치 (루프 조건 검사)
   724→      const loopConditionOffset = this.builder.getCurrentOffset();
   725→
   726→      // 4. len() 호출 및 조건 체크: index >= len(iterable)이면 루프 종료
   727→      const indexReg = this.allocRegister();      // 인덱스
   728→      const lenFuncReg = this.allocRegister();    // len 함수
   729→      const lengthReg = this.allocRegister();     // 배열 길이
   730→      const condReg = this.allocRegister();       // 조건 (index < length)
   731→
   732→      // 인덱스 로드
   733→      this.builder.emit(Opcode.LOAD_GLOBAL, [indexReg, indexVarName]);
   734→
   735→      // len() 호출
   736→      const lenGlobalIdx = this.builder.addGlobal('len');
   737→      this.builder.emit(Opcode.LOAD_GLOBAL, [lenFuncReg, lenGlobalIdx]);
   738→      this.builder.emit(Opcode.CALL, [lengthReg, lenFuncReg, 1, iterReg]);
   739→
   740→      // 조건: index < length
   741→      this.builder.emit(Opcode.LT, [condReg, indexReg, lengthReg]);
   742→
   743→      // 조건 거짓이면 루프 끝으로 점프
   744→      const jumpFalseOffset = this.builder.getCurrentOffset();
   745→      this.builder.emit(Opcode.JUMP_IF_FALSE, [condReg, 0]); // placeholder
   746→
   747→      // 레지스터 정리 (더 이상 사용하지 않음)
   748→      this.freeRegister(lenFuncReg);
   749→      this.freeRegister(lengthReg);
   750→      this.freeRegister(condReg);
   751→
   752→      // 5. 현재 아이템 추출: item = iterable[index]
   753→      const itemReg = this.allocRegister();
   754→      this.builder.emit(Opcode.INDEX_GET, [itemReg, iterReg, indexReg]);
   755→      this.freeRegister(indexReg); // 더 이상 사용하지 않음
   756→
   757→      // 6. 루프 변수 저장: targetName = item
   758→      this.builder.emit(Opcode.STORE_GLOBAL, [targetName, itemReg]);
   759→      this.freeRegister(itemReg);
   760→
   761→      // 7. 루프 본문 컴파일
   762→      for (const s of stmt.body) {
   763→        this.compileStatement(s);
   764→      }
   765→
   766→      // 8. 인덱스 증가: _index_xxx = _index_xxx + 1
   767→      const indexIncReg = this.allocRegister();
   768→      const oneConstIdx = this.builder.addConstant(1);
   769→      const oneReg = this.allocRegister();
   770→
   771→      this.builder.emit(Opcode.LOAD_GLOBAL, [indexIncReg, indexVarName]);
   772→      this.builder.emit(Opcode.LOAD_CONST, [oneReg, oneConstIdx]);
   773→
   774→      const nextIndexReg = this.allocRegister();
   775→      this.builder.emit(Opcode.ADD, [nextIndexReg, indexIncReg, oneReg]);
   776→      this.builder.emit(Opcode.STORE_GLOBAL, [indexVarName, nextIndexReg]);
   777→
   778→      this.freeRegister(indexIncReg);
   779→      this.freeRegister(oneReg);
   780→      this.freeRegister(nextIndexReg);
   781→
   782→      // 9. 루프 시작으로 되돌아가기
   783→      this.builder.emit(Opcode.JUMP, [loopConditionOffset]);
   784→
   785→      // 10. 루프 종료 위치 설정 (조건 거짓일 때의 점프 대상)
   786→      const loopEndOffset = this.builder.getCurrentOffset();
   787→      const jumpFalseInstr = this.builder.code[jumpFalseOffset];
   788→      if (jumpFalseInstr) {
   789→        jumpFalseInstr.args[1] = loopEndOffset;
   790→      }
   791→
   792→      this.freeRegister(iterReg);
   793→    }
   794→
   795→    this.loopStack.pop();
   796→  }
   797→
   798→  /**
   799→   * While 루프 컴파일
   800→   */
   801→  private compileWhileLoop(stmt: any): void {
   802→    const loopStartOffset = this.builder.getCurrentOffset();
